      case DbUnlockOutcome_WrongSecret():
        sse_encode_i_32(1, serializer);
      case DbUnlockOutcome_Cancelled():
        sse_encode_i_32(2, serializer);
      case DbUnlockOutcome_PluginError(field0: final field0):
        sse_encode_i_32(3, serializer);
