  /// the Dart caller pays one FRB roundtrip instead of N
  /// (one per file + one per directory). Hard depth cap of 100.
  Future<void> removeDirRecursive({required String path}) => RustLib
      .instance
      .api
      .crateApiSftpSshSftpRemoveDirRecursive(that: this, path: path);

  /// Remove a regular file.
  Future<void> removeFile({required String path}) => RustLib.instance.api
      .crateApiSftpSshSftpRemoveFile(that: this, path: path);

  /// Rename / move.
  Future<void> rename({required String oldPath, required String newPath}) =>
      RustLib.instance.api.crateApiSftpSshSftpRename(
        that: this,
        oldPath: oldPath,
        newPath: newPath,
      );

  /// Stat a path (resolves symlinks).
  Future<SftpFileMetadata> stat({required String path}) =>
      RustLib.instance.api.crateApiSftpSshSftpStat(that: this, path: path);

  /// Stat a path without resolving symlinks.
  Future<SftpFileMetadata> statSymlink({required String path}) => RustLib
      .instance
      .api
      .crateApiSftpSshSftpStatSymlink(that: this, path: path);

  /// Streamed single-file download — mirror of
  /// [`stream_upload_file`].
  Stream<DbTransferProgressBytes> streamDownloadFile({
    required String remotePath,
    required String localPath,
  }) => RustLib.instance.api.crateApiSftpSshSftpStreamDownloadFile(
    that: this,
    remotePath: remotePath,
    localPath: localPath,
  );

  /// Streamed single-file upload. Replaces the per-chunk Dart
  /// `writeAll` loop on the SFTP transfer hot path — the entire
  /// 64 KiB-chunked copy now lives Rust-side; the Dart side
  /// receives a single FRB call's worth of stream events instead
  /// of N round-trips per file. `sink` receives one
  /// [`DbTransferProgressBytes`] per chunk written; subscription
  /// cancellation closes the sink → next `add` fails →
  /// `lfs_core` translates to `Error::Cancelled`.
  Stream<DbTransferProgressBytes> streamUploadFile({
    required String localPath,
    required String remotePath,
  }) => RustLib.instance.api.crateApiSftpSshSftpStreamUploadFile(
    that: this,
    localPath: localPath,
    remotePath: remotePath,
  );

  /// Recursively upload a local directory tree into a remote
  /// path. The walker (in `lfs_core::sftp`) handles mkdir +
  /// per-file streaming + depth cap; this shim forwards the
  /// per-file completion event to `sink`. Dart cancellation
  /// (subscription cancelled) closes the sink → the next
  /// progress emission fails → the walker returns
  /// `Error::Cancelled`.
  Stream<DbTransferProgress> uploadDir({
    required String localDir,
    required String remoteDir,
  }) => RustLib.instance.api.crateApiSftpSshSftpUploadDir(
    that: this,
    localDir: localDir,
    remoteDir: remoteDir,
  );

  /// Overwrite a small file with `data`.
  Future<void> writeFile({required String path, required List<int> data}) =>
      RustLib.instance.api.crateApiSftpSshSftpWriteFile(
        that: this,
        path: path,
        data: data,
      );
}

